import numpy as np
from scipy.optimize import milp, LinearConstraint, Bounds
ones={(r,c) for r,row in enumerate(top) for c,v in enumerate(row) if v==1}
shapes=[('9a',7,2),('4a',6,2),('4b',6,2),('9b',1,2),('9c',1,2),('6a',6,5),('6b',4,1),('2a',7,3),('7a',2,4),('5a',3,2),('8a',2,2),('8b',2,2),('0a',1,1),('0b',1,1),('0c',1,1),('0d',1,1)]
placements=[]
for oi,(name,h,w) in enumerate(shapes):
    ps=[]
    for r in range(10-h+1):
      for c in range(25-w+1):
       cells=frozenset((r+dr,c+dc) for dr in range(h) for dc in range(w))
       if cells<=ones: ps.append((r,c,cells))
    placements.append(ps)
    print(name,len(ps))
vars=[(oi,p) for oi,ps in enumerate(placements) for p in ps]
idx={v:i for i,v in enumerate(vars)}
n=len(vars)
rows=[]; lbs=[]; ubs=[]
# object once
for oi in range(len(shapes)):
 row=np.zeros(n)
 for p in placements[oi]:row[idx[(oi,p)]]=1
 rows.append(row);lbs.append(1);ubs.append(1)
# each cell coverage at least 1
for cell in ones:
 row=np.zeros(n)
 for oi,ps in enumerate(placements):
  for p in ps:
   if cell in p[2]:row[idx[(oi,p)]]=1
 rows.append(row);lbs.append(1);ubs.append(np.inf)
# sum placements =127 fixed automatically, coverage sum=125+2=127
row=np.zeros(n)
for (oi,p),i in idx.items():
 for cell in p[2]:row[i]+=1/len(ones) # not correct
# total incidence constraint
row=np.zeros(n)
for cell in ones:
 for oi,ps in enumerate(placements):
  for p in ps:
   if cell in p[2]:row[idx[(oi,p)]]+=1
rows.append(row);lbs.append(127);ubs.append(127)
res=milp(np.zeros(n),integrality=np.ones(n),bounds=Bounds(0,1),constraints=LinearConstraint(np.array(rows),lbs,ubs),options={'time_limit':10})
print(res.success,res.message)
if res.x is not None:
 sol=[vars[i] for i,x in enumerate(res.x) if x>.5]
 for oi,p in sol: print(shapes[oi][0],p[:2])

# drop last total constraint and solve feasibility
res=milp(np.zeros(n),integrality=np.ones(n),bounds=Bounds(0,1),constraints=LinearConstraint(np.array(rows[:-1]),lbs[:-1],ubs[:-1]),options={'time_limit':10})
print(res.success,res.message)
if res.x is not None:
 sol=[vars[i] for i,x in enumerate(res.x) if x>.5]
 for oi,p in sorted(sol): print(shapes[oi][0],p[:2])
 cov={cell:0 for cell in ones}
 for oi,p in sol:
  for cell in p[2]:cov[cell]+=1
 print('overlap',sum(v-1 for v in cov.values()))

# constraints each cell coverage <=1, maximize covered cells (equiv penalties uncovered)
rows2=rows[:len(shapes)]; lb2=lbs[:len(shapes)];ub2=ubs[:len(shapes)]
for cell in ones:
 row=np.zeros(n)
 for oi,ps in enumerate(placements):
  for p in ps:
   if cell in p[2]:row[idx[(oi,p)]]=1
 rows2.append(row);lb2.append(0);ub2.append(1)
c=np.zeros(n)
for (oi,p),i in idx.items():c[i]=-len(p[2])
res=milp(c,integrality=np.ones(n),bounds=Bounds(0,1),constraints=LinearConstraint(np.array(rows2),lb2,ub2),options={'time_limit':10})
print(res.success,res.fun,res.message)
sol=[vars[i] for i,x in enumerate(res.x) if x>.5]
for oi,p in sorted(sol): print(shapes[oi][0],p[:2])
covered=set().union(*(p[2] for oi,p in sol));print('uncovered',ones-covered)

